11:    public static class HexPrefix
12:    {
13:        public static int ByteLength(byte[] path) => path.Length / 2 + 1;
15:        public static void CopyToSpan(byte[] path, bool isLeaf, Span<byte> output)
16:        {
17:            if (output.Length != ByteLength(path)) throw new ArgumentOutOfRangeException(nameof(output));
19:            output[0] = (byte)(isLeaf ? 0x20 : 0x00);
20:            if (path.Length % 2 != 0)
21:            {
22:                output[0] += (byte)(0x10 + path[0]);
23:            }
25:            for (int i = 0; i < path.Length - 1; i += 2)
26:            {
27:                output[i / 2 + 1] =
28:                    path.Length % 2 == 0
29:                        ? (byte)(16 * path[i] + path[i + 1])
30:                        : (byte)(16 * path[i + 1] + path[i + 2]);
31:            }
32:        }
34:        public static byte[] ToBytes(byte[] path, bool isLeaf)
35:        {
36:            byte[] output = new byte[path.Length / 2 + 1];
38:            CopyToSpan(path, isLeaf, output);
40:            return output;
41:        }
43:        public static (byte[] key, bool isLeaf) FromBytes(ReadOnlySpan<byte> bytes)
44:        {
45:            bool isEven = (bytes[0] & 16) == 0;
46:            int nibblesCount = bytes.Length * 2 - (isEven ? 2 : 1);
47:            byte[] path = new byte[nibblesCount];
48:            Span<byte> span = new(path);
49:            if (!isEven)
50:            {
51:                span[0] = (byte)(bytes[0] & 0xF);
52:                span = span[1..];
53:            }
54:            bool isLeaf = bytes[0] >= 32;
55:            bytes = bytes[1..];
57:            Span<ushort> nibbles = MemoryMarshal.CreateSpan(
58:                ref Unsafe.As<byte, ushort>(ref MemoryMarshal.GetReference(span)),
59:                span.Length / 2);
61:            Debug.Assert(nibbles.Length == bytes.Length);
63:            ref byte byteRef = ref MemoryMarshal.GetReference(bytes);
64:            ref ushort lookup16 = ref MemoryMarshal.GetArrayDataReference(Lookup16);
65:            for (int i = 0; i < nibbles.Length; i++)
66:            {
67:                nibbles[i] = Unsafe.Add(ref lookup16, Unsafe.Add(ref byteRef, i));
68:            }
70:            return (path, isLeaf);
71:        }
