  4	using Force.Crc32;
  5	using Nethermind.Core;
  6	using Nethermind.Core.Collections;
  7	using Nethermind.Core.Crypto;
  8	using Nethermind.Core.Specs;
  9	using Nethermind.Specs;
 10	using Nethermind.Synchronization;
 11	using System;
 12	using System.Buffers.Binary;
 13	using System.Collections.Generic;
 14	using System.Numerics;
 15	using System.Runtime.CompilerServices;
 16	using System.Threading;
 17	
 18	namespace Nethermind.Network
 19	{
 20	    public class ForkInfo(ISpecProvider specProvider, ISyncServer syncServer) : IForkInfo
 21	    {
 22	        private readonly Lock _initLock = new();
 23	        private bool _wasInitialized = false;
 24	        private Dictionary<uint, Fork> DictForks { get; set; }
 25	        internal Fork[] Forks { get; set; }
 26	        private bool _hasTimestampFork;
 27	
 28	        internal void EnsureInitialized()
 29	        {
 30	            using Lock.Scope _ = _initLock.EnterScope();
 31	
 32	            if (_wasInitialized) return;
 33	            _wasInitialized = true;
 34	
 35	            Hash256 genesisHash = syncServer.Genesis!.Hash;
 36	
 37	            _hasTimestampFork = specProvider.TimestampFork != ISpecProvider.TimestampForkNever;
 38	            ForkActivation[] transitionActivations = specProvider.TransitionActivations;
 39	            DictForks = new();
 40	            Forks = new Fork[transitionActivations.Length + 1];
 41	            byte[] blockNumberBytes = new byte[8];
 42	            uint crc = Crc32Algorithm.Append(0, genesisHash.ThreadStaticBytes());
 43	            // genesis fork activation
 44	            SetFork(0, crc, new((0, null), new ForkId(crc, transitionActivations.Length > 0 ? transitionActivations[0].Activation : 0)));
 45	            for (int index = 0; index < transitionActivations.Length; index++)
 46	            {
 47	                ForkActivation forkActivation = transitionActivations[index];
 48	                BinaryPrimitives.WriteUInt64BigEndian(blockNumberBytes, forkActivation.Activation);
 49	                crc = Crc32Algorithm.Append(crc, blockNumberBytes);
 50	                SetFork(index + 1, crc, new(forkActivation, new ForkId(crc, GetNextActivation(index, transitionActivations))));
 51	            }
 52	        }
 53	
 54	        [MethodImpl(MethodImplOptions.AggressiveInlining)]
 55	        private void SetFork(int index, uint crc, Fork fork)
 56	        {
 57	            Forks[index] = fork;
 58	            DictForks.Add(crc, fork);
 59	        }
 60	
 61	        private static ulong GetNextActivation(int index, ForkActivation[] transitionActivations)
 62	        {
 63	            static T? GetActivationPrimitive<T>(T? activation, T delta) where T : struct, INumber<T>, IMinMaxValue<T> =>
 64	                activation is null ? default : activation < T.MaxValue - delta ? activation : T.Zero;
 65	
 66	            static ulong GetActivation(ForkActivation forkActivation) =>
 67	                GetActivationPrimitive(forkActivation.Timestamp, 4UL)
 68	                ?? (ulong)GetActivationPrimitive(forkActivation.BlockNumber, 4L);
 69	
 70	            index += 1;
 71	            return index < transitionActivations.Length
 72	                ? GetActivation(transitionActivations[index])
 73	                : 0;
 74	        }
 75	
 76	        public ForkId GetForkId(long headNumber, ulong headTimestamp)
 77	        {
 78	            EnsureInitialized();
 79	
 80	            return Forks.TryGetSearchedItem(
 81	                new ForkActivation(headNumber, headTimestamp),
 82	                CompareTransitionOnActivation, out Fork fork)
 83	                ? fork.Id
 84	                : throw new InvalidOperationException("Fork not found");
 85	        }
 86	
 87	        private static int CompareTransitionOnActivation(ForkActivation activation, Fork transition) =>
 88	            activation.CompareTo(transition.Activation);
 89	
 90	        /// <summary>
 91	        /// Verify that the forkid from peer matches our forks.
 92	        /// </summary>
 93	        /// <param name="peerId"></param>
 94	        /// <param name="head"></param>
 95	        /// <returns></returns>
 96	        public ValidationResult ValidateForkId(ForkId peerId, BlockHeader? head)
 97	        {
 98	            // Bit of a hack, if Next value is >= than genesis of oldest supported network it is timestamp.
 99	            // Potentially we can parametrize it based on Spec provider, but not worth it for now
100	            // We support block forks up to 1,4 bln blocks
101	            [MethodImpl(MethodImplOptions.AggressiveInlining)]
102	            static bool IsTimestamp(ulong next) => next >= MainnetSpecProvider.GenesisBlockTimestamp;
103	
104	            EnsureInitialized();
105	
106	            if (head is null) return ValidationResult.Valid;
107	            if (!DictForks.TryGetValue(peerId.ForkHash, out Fork found))
108	            {
109	                // Remote is on fork that does not exist for local. remote is incompatible or local is stale.
110	                return ValidationResult.IncompatibleOrStale;
111	            }
112	
113	            bool forkIsLast = found.Id.Next == 0;
114	            bool peerForkIsLast = peerId.Next == 0;
115	
116	            bool usingTimestamp = _hasTimestampFork
117	                                  && (forkIsLast || IsTimestamp(found.Id.Next)) &&
118	                                  (peerForkIsLast || IsTimestamp(peerId.Next));
119	
120	            ulong headActivation = usingTimestamp ? head.Timestamp : (ulong)head.Number;
121	
122	            if (found.Id.Next != peerId.Next) // if the next fork is different
123	            {
124	                bool headPastLocalFork = headActivation >= found.Id.Next;
125	                if (peerForkIsLast && !forkIsLast && headPastLocalFork)
126	                {
127	                    // Remote does not know about a fork that local has already went through. remote is stale.
128	                    return ValidationResult.RemoteStale;
129	                }
130	
131	                bool headPastPeerFork = headActivation >= peerId.Next;
132	                if (!peerForkIsLast && headPastPeerFork)
133	                {
134	                    // remote is expecting a fork that we passed but did not go through. remote is incompatible or local is stale.
135	                    return ValidationResult.IncompatibleOrStale;
136	                }
137	            }
138	
139	            return ValidationResult.Valid;
140	        }
141	
142	        public ForkActivationsSummary GetForkActivationsSummary(BlockHeader? head)
143	        {
144	            EnsureInitialized();
145	
146	            ForkActivation headActivation = new(head?.Number ?? 0, head?.Number == 0 ? 0 : head?.Timestamp ?? 0);
147	
148	            int indexOfActive = Forks.Length - 1;
149	
150	            do
151	            {
152	                ForkActivation fork = Forks[indexOfActive].Activation;
153	
154	                if (fork.Timestamp.HasValue ? fork.Timestamp <= headActivation.Timestamp : fork.BlockNumber <= headActivation.BlockNumber)
155	                {
156	                    break;
157	                }
158	
159	                indexOfActive--;
160	            } while (indexOfActive != 0);
161	
162	            // The fix for post-merge genesis
163	            Fork currentFork = Forks[indexOfActive];
164	
165	            if (currentFork.Activation.BlockNumber is 0 && currentFork.Activation.Timestamp is null)
166	            {
167	                currentFork = new Fork(new ForkActivation(0, 0), currentFork.Id);
168	            }
169	
170	            bool isNextPresent = GetNextActivation(indexOfActive - 1, specProvider.TransitionActivations) is not 0;
171	
172	            return new ForkActivationsSummary
173	            {
174	                Current = currentFork,
175	                Next = isNextPresent ? new Fork(Forks[indexOfActive + 1].Activation, Forks[indexOfActive + 1].Id) : null,
176	                Last = isNextPresent ? new Fork(Forks[^1].Activation, Forks[^1].Id) : null,
177	            };
178	        }
179	    }
180	}

